WITH w AS (SELECT b.mktcode,b.tgtcode,b.bizdate,b.volume,t.ma5,t.ma20,LAG(t.ma5) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS p5,LAG(t.ma20) OVER(PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate) AS p20 FROM `newzl`.`hsj_stock_hq_basic` AS b LEFT JOIN `newzl`.`hsj_stock_hq_basic_technical` AS t ON t.mktcode=b.mktcode AND t.tgtcode=b.tgtcode AND t.bizdate=b.bizdate) SELECT mktcode,tgtcode,bizdate FROM w WHERE bizdate='2026-04-14' AND ma5>ma20 AND p5<=p20 AND volume>0;
